# GEMINA8 V4 - Keras -> TensorFlow.js converter for Google Colab\n# Upload GEMINA8_V4_EXPORT.zip, then run this cell.\nimport os, sys, types, zipfile, shutil, subprocess, pathlib\nimport numpy as np\n# Compatibility patches for environments where tensorflowjs expects removed distutils / np.object\ntry:\n    import setuptools._distutils as _du\n    sys.modules.setdefault('distutils', _du)\nexcept Exception: pass\nif not hasattr(np,'object'): np.object = object\nsubprocess.run([sys.executable,'-m','pip','install','-q','tensorflowjs==4.22.0'],check=True)\nimport tensorflow as tf\nimport tensorflowjs as tfjs\nZIP='/content/GEMINA8_V4_EXPORT.zip'\nOUT='/content/tfjs'\nos.makedirs(OUT,exist_ok=True)\nwith zipfile.ZipFile(ZIP) as z: z.extractall('/content/gemina8_v4')\nfor name in ['LSTM','GRU','TRANSFORMER']:\n    model=tf.keras.models.load_model(f'/content/gemina8_v4/{name}_best.keras',compile=False)\n    dest=f'{OUT}/{name}'\n    os.makedirs(dest,exist_ok=True)\n    tfjs.converters.save_keras_model(model,dest)\nprint('DONE:', os.listdir(OUT))\nshutil.make_archive('/content/GEMINA8_TFJS_MODELS','zip','/content/tfjs')\nprint('/content/GEMINA8_TFJS_MODELS.zip')\n